/// <summary>
/// Gets maximum sequence number.
/// </summary>
/// <param name = "_profileId">Profile Id.</param>
/// <returns>Maximum sequence number.</returns>
public static int getMaxSeqNumber(METFulfilmentProfileId _profileId)
{
    return (select maxof(Sequence) from METFulfilmentRule
                where METFulfilmentRule.ProfileId == _profileId).Sequence;
}

/// <summary>
/// Sets sequence number.
/// </summary>
public void setSeqNumber()
{
    this.Sequence = METFulfilmentRule::getMaxSeqNumber(this.ProfileId) + 1;
}

/// <summary>
/// Inserts the record.
/// </summary>
public void insert()
{
    if (!this.Sequence)
    {
        this.setSeqNumber();
    }

    super();
}

/// <summary>
/// Finds and returns table record <c>METFulfilmentRule</c>.
/// </summary>
/// <param name = "_profileId">Profile Id.</param>
/// <param name = "_type">rule type.</param>
/// <param name = "_forUpdate">ForUpdate parameter.</param>
/// <returns>Record <c>METFulfilmentRule</c>.</returns>
public static METFulfilmentRule find(METFulfilmentProfileId _profileId,
                                     METFulfilmentRuleType _type,
                                     boolean _forUpdate = true)
{
    METFulfilmentRule rule;

    rule.selectForUpdate(_forUpdate);

    select firstonly rule
        where rule.ProfileId == _profileId
        &&    rule.Type == _type;

    return rule;
}

/// <summary>
/// Constructs value lookup.
/// </summary>
/// <param name = "_formControl">Form control.</param>
/// <param name = "_rule">METFulfilmentRule record.</param>
public static void valueLookup(FormStringControl _formControl, METFulfilmentRule _rule)
{
    METFulfilmentRuleValueLookupTmp lookupTmp;
    SysTableLookup                  lookup;

    lookup = SysTableLookup::newParameters(tableNum(METFulfilmentRuleValueLookupTmp), _formControl);

    switch (_rule.Type)
    {
        case METFulfilmentRuleType::CSDTOType:
            lookupTmp = METFulfilmentRuleValueLookupTmp::stageCSDTOType();
            break;

        case METFulfilmentRuleType::OrderType:
            lookupTmp = METFulfilmentRuleValueLookupTmp::stageOrderType();
            break;
    }

    lookup.addLookupField(fieldNum(METFulfilmentRuleValueLookupTmp, Value), true);
    lookup.parmTmpBuffer(lookupTmp);
    lookup.performFormLookup();
}

/// <summary>
/// Validates data befortre writing.
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();



    return ret;
}

/// <summary>
/// Validatrs rule types.
/// </summary>
/// <returns>True if valid; otherwise, false</returns>
private boolean validateRuleTypes()
{
    boolean ret = true;

    switch (this.Type)
    {
        case METFulfilmentRuleType::UOMConversion:
            ret = this.validateUOMConversion();
            break;
        case METFulfilmentRuleType::Customer:
            ret = this.validateCustomer();
            break;
        case METFulfilmentRuleType::Route:
            ret = this.validateRoute();
            break;

    }

    return ret;
}

/// <summary>
/// Validates UOM converison.
/// </summary>
/// <returns>True if valid; otherwise, false.</returns>
private boolean validateUOMConversion()
{
    METFulfilmentRule rule;
    boolean ret = true;

    switch (this.Apply)
    {
        case METFulfilmentRuleApply::RemainderToEA, 
             METFulfilmentRuleApply::RemainderToEAResidualInv:

            select firstonly RecId from rule
                where rule.ProfileId == this.ProfileId
                &&    rule.Type      == this.Type
                &&    rule.Apply     == METFulfilmentRuleApply::EAToSalesUnit;

            if (!rule.RecId)
            {
                ret = checkFailed(strFmt("@MET:FulfilmentRuleSeqError", enum2Str(this.Type),
                                                                        enum2Str(this.Apply),
                                                                        enum2Str(this.Type),
                                                                        enum2Str(enum2Str(METFulfilmentRuleApply::EAToSalesUnit))));
            }
            break;

    }

    return ret;
}

private boolean validateCustomer()
{
    METFulfilmentRule rule;
    boolean ret = true;

    if (this.Apply == METFulfilmentRuleApply::CSDInternalCustomer)
    {
        select firstonly RecId from rule
            where rule.ProfileId == this.ProfileId
            &&    rule.Type      == METFulfilmentRuleType::CSDTOType
            &&    rule.Apply     == METFulfilmentRuleApply::SetValue;
    }

    if (!rule.RecId)
    {
        ret = checkFailed(strFmt("@MET:FulfilmentRuleSeqError", enum2Str(this.Type),
                                                                enum2Str(this.Apply),
                                                                enum2Str(METFulfilmentRuleType::CSDTOType),
                                                                enum2Str(METFulfilmentRuleApply::SetValue)));
    }

    return ret;
}

private boolean validateRoute()
{
    METFulfilmentRule rule;
    boolean ret = true;

    if (this.Apply == METFulfilmentRuleApply::InternalTORoute)
    {
        select firstonly RecId from rule
            where rule.ProfileId == this.ProfileId
            &&    rule.Type      == METFulfilmentRuleType::Customer
            &&    rule.Apply     == METFulfilmentRuleApply::CSDInternalCustomer;
    }

    if (!rule.RecId)
    {
        ret = checkFailed(strFmt("@MET:FulfilmentRuleSeqError", enum2Str(this.Type),
                                                                enum2Str(this.Apply),
                                                                enum2Str(METFulfilmentRuleType::Customer),
                                                                enum2Str(METFulfilmentRuleApply::CSDInternalCustomer)));
    }

    return ret;
}
